pragma solidity >=0.8.0;
contract StoragePackingProbeStrBytesMin {
    string public text;
    bytes public blob;

    function setText(string memory t) public { text = t; }
    function setBlob(bytes memory bl) public { blob = bl; }
    function length() public view returns (uint256) { return bytes(text).length + blob.length; }
}
